#!/usr/bin/env node

/**
 * YouTube Shorts auto-upload script.
 *
 * Discovers MP4 clips generated by tiktok-clip-generator.js in the clips/
 * directory and uploads them as YouTube Shorts via the YouTube Data API v3.
 *
 * Each upload:
 *   - Title: "ARTIST — TRACK [Genre] #Shorts"
 *   - Description: site link + UTM params + hashtags
 *   - Category: Music (ID 10)
 *   - Tags: artist, genre, rock, metal, shorts
 *   - Made for kids: false
 *   - Privacy: public
 *
 * YouTube Shorts are detected automatically by YouTube when:
 *   - Video is vertical (aspect ratio ≤ 1:1), which our clips are (1080×1920)
 *   - Duration ≤ 60 seconds, which our clips are (12 seconds)
 *   - Title or description includes #Shorts
 *
 * Quota: each upload costs ~1,600 units. Free tier is 10,000 units/day,
 * so we cap at 2–3 uploads per day.
 *
 * Usage:
 *   node scripts/youtube-shorts-upload.js --dry-run       (list candidates)
 *   node scripts/youtube-shorts-upload.js --force         (upload one, bypass daily cap)
 *   node scripts/youtube-shorts-upload.js --count 3       (upload up to 3)
 *
 * Prerequisites:
 *   npm install googleapis
 *   Set YOUTUBE_CLIENT_ID and YOUTUBE_CLIENT_SECRET in .env.local
 *   Run once interactively to complete OAuth consent flow
 *   Run scripts/tiktok-clip-generator.js first to generate clips
 *
 * Required env:
 *   YOUTUBE_CLIENT_ID — Google OAuth 2.0 client ID
 *   YOUTUBE_CLIENT_SECRET — Google OAuth 2.0 client secret
 *   DATABASE_URL — MariaDB connection string
 *
 * Optional env:
 *   YOUTUBE_MAX_UPLOADS_PER_DAY — max uploads per day (default: 2)
 *   YOUTUBE_CLIPS_DIR — path to clips directory (default: clips/)
 *   YOUTUBE_UPLOAD_STATE_PATH — state file path
 *   APP_URL — site URL for link in description (default: https://yehthatrocks.com)
 *
 * Phase 4.2 — YouTube Shorts pipeline (TRAFFIC_ROADMAP.md)
 */

"use strict";

const path = require("node:path");
const fs = require("node:fs");
const { PrismaClient } = require("@prisma/client");
const { PrismaMariaDb } = require("@prisma/adapter-mariadb");
const { getYouTubeClient } = require("./lib/youtube-auth");

// Load env before anything else
try { require("dotenv").config({ path: path.resolve(process.cwd(), "apps/web/.env.local") }); } catch {}
try { require("dotenv").config(); } catch {}

const {
  loadEnv,
  toPositiveInt,
  ensureDirFor,
  readState,
  writeState,
} = require("./lib/social-share-utils");

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

const CLIPS_DIR = path.resolve(
  process.cwd(),
  (process.env.YOUTUBE_CLIPS_DIR || "clips").trim(),
);
const APP_URL = (process.env.APP_URL || "https://yehthatrocks.com").trim().replace(/\/$/, "");
const MUSIC_CATEGORY_ID = "10"; // YouTube category: Music

// ---------------------------------------------------------------------------
// Clip discovery
// ---------------------------------------------------------------------------

/**
 * Parse a clip filename to extract the YouTube video ID.
 *
 * Expected format from tiktok-clip-generator.js:
 *   dQw4w9WgXcQ.mp4
 *
 * Returns the videoId (filename without extension).
 */
function parseClipVideoId(filename) {
  const match = filename.match(/^([A-Za-z0-9_-]{11})\.mp4$/);
  return match ? match[1] : null;
}

/**
 * Scan the clips directory for uploaded MP4 files.
 * Returns array of { filename, filepath, videoId, sizeBytes, mtime }.
 */
function scanClips() {
  if (!fs.existsSync(CLIPS_DIR)) {
    return [];
  }

  const entries = fs.readdirSync(CLIPS_DIR, { withFileTypes: true });
  const clips = [];

  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith(".mp4")) {
      continue;
    }

    const videoId = parseClipVideoId(entry.name);
    if (!videoId) {
      continue;
    }

    const filepath = path.join(CLIPS_DIR, entry.name);
    let stat;
    try {
      stat = fs.statSync(filepath);
    } catch {
      continue;
    }

    clips.push({
      filename: entry.name,
      filepath,
      videoId,
      sizeBytes: stat.size,
      mtime: stat.mtime.toISOString(),
    });
  }

  return clips;
}

// ---------------------------------------------------------------------------
// Metadata builder
// ---------------------------------------------------------------------------

/**
 * Build the YouTube Shorts title.
 * Format: "ARTIST — TRACK [Genre] #Shorts"
 * YouTube auto-detects Shorts when #Shorts is in the title/description.
 */
function buildTitle(artist, title, genre) {
  const cleanArtist = String(artist || "Unknown Artist").trim();
  const cleanTrack = String(title || "Unknown Track").trim();
  const cleanGenre = String(genre || "Rock / Metal").trim();

  // YouTube title limit is 100 characters
  const suffix = " #Shorts";
  const maxBase = 100 - suffix.length;
  let base = `${cleanArtist} — ${cleanTrack} [${cleanGenre}]`;

  if (base.length > maxBase) {
    const available = maxBase - 3;
    base = `${cleanArtist} — ${cleanTrack}`;
    if (base.length > available) {
      base = base.slice(0, available - 3) + "...";
    }
  }

  return base + suffix;
}

/**
 * Build the video description with site link, UTM params, and hashtags.
 */
function buildDescription(artist, title, genre, videoId) {
  const cleanArtist = String(artist || "Unknown Artist").trim();
  const cleanTrack = String(title || "Unknown Track").trim();
  const cleanGenre = String(genre || "Rock / Metal").trim();

  const shareUrl = `${APP_URL}/s/${encodeURIComponent(videoId)}?` + new URLSearchParams({
    utm_source: "youtube",
    utm_medium: "shorts",
    utm_campaign: "autoshare",
  }).toString();

  const lines = [
    `${cleanArtist} — ${cleanTrack}`,
    `Genre: ${cleanGenre}`,
    "",
    `Watch the full video at YehThatRocks: ${shareUrl}`,
    "",
    "#RockMusic #MetalMusic #Shorts #MusicDiscovery",
  ];

  // Add genre-specific hashtag
  const genreTag = cleanGenre
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "")
    .replace(/^(.)/, (c) => c.toUpperCase());
  if (genreTag && !lines[lines.length - 1].toLowerCase().includes(genreTag.toLowerCase())) {
    lines[lines.length - 1] += ` #${genreTag}`;
  }

  return lines.join("\n");
}

/**
 * Build video tags array.
 */
function buildTags(artist, genre) {
  const cleanArtist = String(artist || "").trim();
  const cleanGenre = String(genre || "").trim();

  const tags = ["rock", "metal", "music", "shorts", "yehthatrocks"];

  if (cleanGenre) {
    tags.push(cleanGenre.toLowerCase());
  }

  if (cleanArtist) {
    tags.push(cleanArtist.toLowerCase());
  }

  // Deduplicate and limit to ~20 tags
  return [...new Set(tags)].slice(0, 20);
}

// ---------------------------------------------------------------------------
// Upload
// ---------------------------------------------------------------------------

/**
 * Upload a single clip as a YouTube Short.
 *
 * Uses resumable upload for reliability with large files.
 * Returns the YouTube video ID on success.
 */
async function uploadShort(youtube, clip, metadata) {
  const fileSize = fs.statSync(clip.filepath).size;
  const fileStream = fs.createReadStream(clip.filepath);

  console.log(`[youtube-shorts] Uploading "${metadata.snippet.title}" (${(fileSize / 1024 / 1024).toFixed(1)} MB)...`);

  const response = await youtube.videos.insert({
    part: ["snippet", "status"],
    notifySubscribers: false, // Don't spam subscribers for Shorts
    requestBody: {
      snippet: {
        title: metadata.snippet.title,
        description: metadata.snippet.description,
        tags: metadata.snippet.tags,
        categoryId: MUSIC_CATEGORY_ID,
      },
      status: {
        privacyStatus: "public",
        selfDeclaredMadeForKids: false,
      },
    },
    media: {
      body: fileStream,
    },
  });

  const youtubeVideoId = response.data.id;
  console.log(`[youtube-shorts] ✅ Uploaded: https://youtube.com/shorts/${youtubeVideoId}`);
  return youtubeVideoId;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  loadEnv();

  const args = process.argv.slice(2);
  const dryRun = args.includes("--dry-run");
  const forceRun = args.includes("--force");
  const countArgIndex = args.indexOf("--count");
  const requestedCount = countArgIndex >= 0
    ? toPositiveInt(args[countArgIndex + 1], 1)
    : 1;

  // ── Config ─────────────────────────────────────────────────────────────
  const maxUploadsPerDay = toPositiveInt(process.env.YOUTUBE_MAX_UPLOADS_PER_DAY || "2", 2);
  const uploadCount = Math.min(requestedCount, dryRun ? 10 : maxUploadsPerDay);
  const statePath = path.resolve(
    process.cwd(),
    process.env.YOUTUBE_UPLOAD_STATE_PATH || "logs/youtube-shorts-upload-state.json",
  );

  if (!dryRun && !process.env.DATABASE_URL) {
    throw new Error("DATABASE_URL is not set.");
  }

  // ── Rate limit check ───────────────────────────────────────────────────
  const now = new Date();
  const state = readState(statePath);
  const uploads = Array.isArray(state.uploads) ? state.uploads : [];

  const startOfDay = new Date(now);
  startOfDay.setHours(0, 0, 0, 0);
  const uploadsToday = uploads.filter((u) => {
    const ts = new Date(u.uploadedAt).getTime();
    return Number.isFinite(ts) && ts >= startOfDay.getTime();
  }).length;

  if (!forceRun && uploadsToday >= maxUploadsPerDay) {
    console.log(`[youtube-shorts] Skipped: daily cap reached (${uploadsToday}/${maxUploadsPerDay}).`);
    return;
  }

  // ── Scan clips ──────────────────────────────────────────────────────────
  const clips = scanClips();
  const uploadedIds = new Set(uploads.map((u) => String(u.videoId || "").trim()).filter(Boolean));
  const freshClips = clips.filter((c) => !uploadedIds.has(c.videoId));

  if (freshClips.length === 0) {
    if (clips.length > 0) {
      console.log(`[youtube-shorts] All ${clips.length} clip(s) already uploaded. Generate new clips first.`);
    } else {
      console.log("[youtube-shorts] No clips found. Run tiktok-clip-generator.js first.");
    }
    return;
  }

  // ── Fetch candidate metadata from DB ────────────────────────────────────
  if (!dryRun || true) {
    // Always fetch metadata for dry-run display
    const adapter = new PrismaMariaDb(process.env.DATABASE_URL);
    const prisma = new PrismaClient({ adapter });

    let dbMap;
    try {
      // Fetch metadata for all fresh clips in one query
      const videoIds = freshClips.map((c) => c.videoId);
      const rows = await prisma.$queryRawUnsafe(
        `
          SELECT
            v.videoId,
            COALESCE(NULLIF(TRIM(v.parsedArtist), ''), 'Unknown artist') AS artist,
            COALESCE(NULLIF(TRIM(v.parsedTrack), ''), NULLIF(TRIM(v.title), ''), 'Unknown track') AS title,
            COALESCE(NULLIF(TRIM(v.genre), ''), 'Rock / Metal') AS genre,
            v.id AS internalId
          FROM videos v
          WHERE v.videoId IN (${videoIds.map(() => "?").join(",")})
        `,
        ...videoIds,
      );

      dbMap = {};
      for (const row of rows) {
        dbMap[String(row.videoId || "").trim()] = {
          artist: String(row.artist || "Unknown artist"),
          title: String(row.title || "Unknown track"),
          genre: String(row.genre || "Rock / Metal"),
          internalId: Number(row.internalId) || 0,
        };
      }
    } finally {
      await prisma.$disconnect();
    }

    // ── Prepare candidates ──────────────────────────────────────────────────
    const candidates = [];
    for (const clip of freshClips) {
      const meta = dbMap[clip.videoId] || {
        artist: "Unknown Artist",
        title: "Unknown Track",
        genre: "Rock / Metal",
      };

      candidates.push({
        clip,
        artist: meta.artist,
        title: meta.title,
        genre: meta.genre,
        videoId: clip.videoId,
        title_line: buildTitle(meta.artist, meta.title, meta.genre),
        description: buildDescription(meta.artist, meta.title, meta.genre, clip.videoId),
        tags: buildTags(meta.artist, meta.genre),
      });
    }

    const toProcess = candidates.slice(0, uploadCount);

    // ── Dry-run ──────────────────────────────────────────────────────────────
    if (dryRun) {
      console.log(`[youtube-shorts] Dry run — ${freshClips.length} clip(s) available, would upload ${toProcess.length}:`);
      for (const c of toProcess) {
        console.log(JSON.stringify({
          clip: c.clip.filename,
          videoId: c.videoId,
          title: c.title_line,
          artist: c.artist,
          track: c.title,
          genre: c.genre,
          sizeMB: (c.clip.sizeBytes / 1024 / 1024).toFixed(2),
          tags: c.tags,
        }, null, 2));
        console.log("---");
      }
      return;
    }

    if (toProcess.length === 0) {
      console.log("[youtube-shorts] No candidates to upload.");
      return;
    }

    // ── Upload ──────────────────────────────────────────────────────────────
    console.log(`[youtube-shorts] Uploading ${toProcess.length} clip(s)...`);

    const youtube = await getYouTubeClient();
    const newUploads = [];

    for (const candidate of toProcess) {
      try {
        const youtubeVideoId = await uploadShort(youtube, candidate.clip, {
          snippet: {
            title: candidate.title_line,
            description: candidate.description,
            tags: candidate.tags,
          },
        });

        newUploads.push({
          uploadedAt: new Date().toISOString(),
          videoId: candidate.videoId,
          youtubeVideoId,
          artist: candidate.artist,
          title: candidate.title,
          genre: candidate.genre,
          clipFile: candidate.clip.filename,
        });

        // Small delay between uploads to be polite
        if (toProcess.indexOf(candidate) < toProcess.length - 1) {
          await new Promise((resolve) => setTimeout(resolve, 5000));
        }
      } catch (err) {
        console.error(`[youtube-shorts] ❌ Failed to upload ${candidate.clip.filename}:`, err?.message || err);
        // Continue with next candidate
      }
    }

    // ── Update state ────────────────────────────────────────────────────────
    const nextState = {
      lastRunAt: now.toISOString(),
      uploads: [...uploads, ...newUploads].slice(-1000),
    };
    writeState(statePath, nextState);

    console.log(`[youtube-shorts] Done. ${newUploads.length} uploaded, ${uploadsToday + newUploads.length}/${maxUploadsPerDay} today.`);
  }
}

main().catch((error) => {
  console.error("[youtube-shorts] Failed:", error?.message || error);
  process.exit(1);
});
